+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.vet.domain.Specialty;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.grid.GridVariant;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.orderedlayout.FlexComponent;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.data.provider.DataProvider;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.theme.lumo.LumoUtility;
+
+import java.util.stream.Collectors;
+
+/** UC-002: View Veterinarians. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VeterinariansView extends VerticalLayout {
+
+    private transient VetRepository vetRepository;
+
+    public VeterinariansView(VetRepository vetRepository) {
+        this.vetRepository = vetRepository;
+
+        setSizeFull();
+        setPadding(false);
+        setSpacing(false);
+        setAlignItems(FlexComponent.Alignment.CENTER);
+
+        VerticalLayout page = new VerticalLayout();
+        page.setWidthFull();
+        page.setMaxWidth("76rem");
+        page.setPadding(false);
+        page.setSpacing(false);
+        page.addClassNames(LumoUtility.Padding.Horizontal.XLARGE,
+                LumoUtility.Padding.Vertical.XLARGE);
+
+        H1 heading = new H1("Veterinarians");
+        heading.addClassNames(LumoUtility.FontSize.XXXLARGE,
+                LumoUtility.FontWeight.BOLD,
+                LumoUtility.Margin.NONE);
+
+        Paragraph introduction = new Paragraph(
+                "Meet the clinicians behind your pet’s care. Browse their specialties to find the right expertise.");
+        introduction.addClassNames(LumoUtility.TextColor.SECONDARY,
+                LumoUtility.Margin.Top.SMALL,
+                LumoUtility.Margin.Bottom.LARGE);
+
+        Grid<Vet> veterinarians = createVeterinariansGrid();
+
+        page.add(heading, introduction, veterinarians);
+        add(page);
+    }
+
+    private Grid<Vet> createVeterinariansGrid() {
+        Grid<Vet> grid = new Grid<>();
+        grid.setWidthFull();
+        grid.setHeight("68vh");
+        grid.setMinHeight("22rem");
+        grid.setEmptyStateText("No veterinarians are registered.");
+        grid.getElement().setAttribute("aria-label", "Veterinarians");
+        grid.addThemeVariants(GridVariant.NO_BORDER, GridVariant.ROW_STRIPES);
+
+        grid.addColumn(Vet::firstName)
+                .setHeader("First name")
+                .setAutoWidth(true);
+        grid.addColumn(Vet::lastName)
+                .setHeader("Last name")
+                .setAutoWidth(true);
+        grid.addColumn(VeterinariansView::formatSpecialties)
+                .setHeader("Specialties")
+                .setFlexGrow(1);
+
+        grid.setDataProvider(DataProvider.fromCallbacks(
+                query -> this.vetRepository.findPage(query.getOffset(), query.getLimit()),
+                query -> this.vetRepository.count()));
+        return grid;
+    }
+
+    private static String formatSpecialties(Vet vet) {
+        if (vet.specialties().isEmpty()) {
+            return "none";
+        }
+        return vet.specialties().stream()
+                .map(Specialty::name)
+                .collect(Collectors.joining(", "));
+    }
+}
